entries[216923] = { ["name"] = "Anhängerin: Julia Celeste", ["text"] = "Sofort\nAponi Lichtmähne, Anführerin der aufsteigenden Sonnenläuferpaladine, einte ihr nach Wahrheit und Wissen dürstendes Volk. Was ist die wahre Natur des Lichts? Warum gewährt es uns seine Stärke? Aponi ist fest entschlossen, Antworten auf diese brennenden Fragen zu finden, und hat keine Hemmungen, alles und jeden, der ihr dabei im Weg steht, zu beseitigen." }
